package org.brightstats.stats;
import java.util.*;
import java.util.function.IntConsumer;
/** Full-case multi-level composite hierarchy; no frozen intermediate score bootstrap. */
public final class HierarchyPipeline {
 private HierarchyPipeline(){}
 public record Model(List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,List<HigherOrderPls.Specification> stages){public Model{blocks=List.copyOf(blocks);edges=List.copyOf(edges);Objects.requireNonNull(options);stages=List.copyOf(stages);if(stages.isEmpty()||stages.size()>7)throw new IllegalArgumentException("Specify one to seven hierarchy transitions (two to eight fitted levels).");}}
 public record Fit(Model model,int observations,int originalColumns,List<HigherOrderPls.Fit> stages,List<Bootstrap.Parameter> parameters,double[] estimates,List<String>warnings){public Fit{stages=List.copyOf(stages);parameters=List.copyOf(parameters);estimates=estimates.clone();warnings=List.copyOf(warnings);}@Override public double[] estimates(){return estimates.clone();}}
 public record Resampled(Fit point,Bootstrap.Result inference){}
 public static void validate(int width,Model model){var blocks=model.blocks();var edges=model.edges();for(var specification:model.stages()){HigherOrderPls.validate(width,blocks,edges,specification);var next=HigherOrderPls.stageTwoBlocks(width,blocks,edges,specification);width+=blocks.size();blocks=next;edges=specification.edges();}}
 public static Fit fit(double[][] data,Model model){return compute(data,model,null,null);}
 private static Fit compute(double[][] data,Model model,Fit reference,int[] rows){int width=Matrices.width(data,3);if((long)data.length*width>5000000)throw new IllegalArgumentException("Hierarchy source exceeds five million cells.");double[][] input=Matrices.copy(data);var blocks=model.blocks();var edges=model.edges();var options=model.options();List<HigherOrderPls.Fit> stages=new ArrayList<>();List<String>warnings=new ArrayList<>();HigherOrderPls.PipelineStep result=null;for(int i=0;i<model.stages().size();i++){Matrices.interrupted();result=HigherOrderPls.pipelineStep(input,blocks,edges,options,model.stages().get(i),reference==null?null:reference.stages().get(i),rows);stages.add(result.fit());for(String warning:result.fit().warnings())warnings.add("Transition "+(i+1)+": "+warning);input=result.nextInput();blocks=result.fit().secondStageBlocks();edges=model.stages().get(i).edges();options=model.stages().get(i).options();}warnings.add("All declared levels are estimated from the supplied original cases in every draw. Intermediate generated scores remain analysis variables with explicit stage provenance, not newly observed measurements.");warnings.add("Reported bootstrap targets belong to the final level; intermediate point fits and complete specifications are retained. This is composite PLS, not higher-order factor PLSc.");return new Fit(model,data.length,width,stages,result.parameters(),result.estimates(),warnings);}
 public static Resampled bootstrap(double[][] data,Model model,Bootstrap.Options settings,IntConsumer progress){if(settings.convention()!=RegressionBootstrap.Convention.STANDARD)throw new IllegalArgumentException("Hierarchy inference supports standard percentile/genuine BCa, not legacy PLS interval conventions.");Fit point=fit(data,model);var inference=Resampling.run(data,point.parameters(),point.estimates(),settings,(sample,rows)->compute(sample,model,point,rows).estimates(),progress,"Multi-level composite hierarchy","Each original-case/jackknife draw refits every hierarchy transition. Scores align to original sampled rows before each augmentation and at the final parameter level. No previously exported/frozen score matrix is resampled.");inference=Resampling.suppressTests(inference,p->p.family().equals("R squared"),"R-squared is bounded and does not receive a generic ratio test against zero; empirical intervals are retained.");List<String>warnings=new ArrayList<>(inference.warnings());warnings.addAll(point.warnings());return new Resampled(point,new Bootstrap.Result(inference.options(),inference.method(),inference.randomGenerator(),inference.signHandling(),inference.successful(),inference.failed(),inference.failures(),inference.estimates(),warnings,inference.estimator()));}
}
